SELECT jsonb_build_object(
 'checked_at',now(),
 'bypasses_rls',(SELECT rolbypassrls OR rolsuper FROM pg_roles WHERE rolname=current_user),
 'total_recipes',(SELECT count(*) FROM public.recipes),
 'public_recipes',(SELECT count(*) FROM public.recipes WHERE is_public),
 'old_rows',(SELECT count(*) FROM public.recipes r JOIN expected e ON r.id=e.id AND r.slug=e.old_slug),
 'new_rows',(SELECT count(*) FROM public.recipes r JOIN expected e ON r.id=e.id AND r.slug=e.new_slug),
 'missing_ids',(SELECT count(*) FROM expected e LEFT JOIN public.recipes r ON r.id=e.id WHERE r.id IS NULL),
 'changed_rows',(SELECT count(*) FROM public.recipes r JOIN expected e ON r.id=e.id WHERE NOT r.is_public OR md5((to_jsonb(r)-'slug'-'updated_at'-'times_shown')::text) IS DISTINCT FROM e.content_md5),
 'collisions',(SELECT count(*) FROM public.recipes r JOIN expected e ON r.slug=e.new_slug WHERE r.id<>e.id)
) AS rename_state;
